'use strict';
const neighborhood=EldoriaNeighborhoodModel;neighborhood.ensure(state);
const neighborhoodCSS=document.createElement('link');neighborhoodCSS.rel='stylesheet';neighborhoodCSS.href='city-neighborhood.css?v=1';document.head.append(neighborhoodCSS);
const neighborhoodKinds=['willowLane',...neighborhood.homes.map(h=>h.id)];
function neighborhoodLane(){if(scene!=='home')changeScene('home');cityEnter('willowLane')}
function neighborhoodFront(){if(scene!=='home')changeScene('home');cityLeave()}
const neighborhoodDescriptionBefore=comfortPlaceDescription;comfortPlaceDescription=function(kind){return kind==='willowLane'?'Follow the side path beside your cottage to the neighbors’ front gardens and furnished homes.':neighborhood.home(kind)?.about||neighborhoodDescriptionBefore(kind)};
const neighborhoodWorkBefore=cityWorkLabel;cityWorkLabel=function(kind){return kind==='willowLane'?'Walk the neighborhood lane':neighborhood.home(kind)?'Visit '+neighborhood.home(kind).person:neighborhoodWorkBefore(kind)};
const neighborhoodEnterBefore=cityEnter;cityEnter=function(kind){neighborhoodEnterBefore(kind);if(cityInside===kind&&neighborhood.home(kind)){neighborhood.visit(state,kind,lifeWhere());persist();cityMessage('You arrive at '+cityRoomNames[kind]+'. This is your neighbor’s private home.')}};
function neighborhoodVisit(id){if(scene!=='home')changeScene('home');cityEnter(id);if(cityInside===id)neighborhoodWelcome(id)}
function neighborhoodWelcome(id){const h=neighborhood.home(id);if(!h||!neighborhood.at(id,lifeWhere()))return;const c=atmosphere.conditions(state),here=neighborhood.present(id,c);modal(h.name,'<span class="city-eyebrow">WILLOWWOOD HOMES · A NEIGHBOR’S OWN HOME</span><p>'+lifeEsc(h.about)+'</p><p class="life-dialogue">'+(here?'“'+lifeEsc(h.welcome)+'”':lifeEsc(h.person)+' is out at this hour. A welcome note beside the door says: “'+lifeEsc(h.welcome)+'”')+'</p><p id="neighborhoodFeedback" role="status"></p>');lifePhoto(id);for(const [kind,title]of [['greet',here?'Share a conversation':'Leave a friendly reply'],['tea',here?'Share a pot of tea':'Leave a tea invitation'],['gift','Leave a little bouquet']])action(title,()=>{const r=neighborhood.moment(state,id,kind,lifeWhere(),atmosphere.conditions(state));if(!r.ok){$('neighborhoodFeedback').textContent=r.reason;return}lifeCommit();modal(r.title,'<p class="life-dialogue">'+lifeEsc(r.detail)+'</p>');action('Stay in '+h.name,()=>{$('modal').close();cityDraw()});action('Return to the neighborhood lane',()=>{$('modal').close();neighborhoodLane()})});action('Look around this furnished home',()=>{$('modal').close();cityDraw()});action('Return to the neighborhood lane',()=>{$('modal').close();neighborhoodLane()});action('Go to my own cottage',()=>{$('modal').close();changeScene('home');cityEnter('home')})}
const neighborhoodUseBefore=cityUse;cityUse=function(kind){if(kind===cityInside&&neighborhood.home(kind)){neighborhoodWelcome(kind);return}if(kind==='willowLane'&&kind===cityInside){neighborhoodDirectory();return}neighborhoodUseBefore(kind)};
function neighborhoodDirectory(){modal('The homes down Willowwood Lane','<p>Your cottage opens onto a shared neighborhood. Follow the side lane to four distinct homes, each with its own porch, garden and furnished rooms.</p>');neighborhood.homes.forEach(h=>action('Visit '+h.name,()=>{$('modal').close();neighborhoodVisit(h.id)}));action('Return to my front garden',()=>{$('modal').close();neighborhoodFront()});}
const neighborhoodHotspotsBefore=cityBuildHotspots;cityBuildHotspots=function(){if(scene==='home'&&!cityInside){$('cityHotspots').replaceChildren();cityTarget('Enter · Your Cottage',42,51,()=>cityEnter('home'),'door','home');cityTarget('Neighborhood lane →',83,62,neighborhoodLane,'path','willowLane');return}if(scene==='home'&&cityInside==='willowLane'){$('cityHotspots').replaceChildren();const positions=[[23,51],[78,52],[35,30],[66,31]];neighborhood.homes.forEach((h,i)=>cityTarget('Visit · '+h.name,...positions[i],()=>neighborhoodVisit(h.id),'door',h.id));cityTarget('← Back to my cottage',50,65,neighborhoodFront,'path','home');return}if(scene==='home'&&neighborhood.home(cityInside)){$('cityHotspots').replaceChildren();const h=neighborhood.home(cityInside);cityTarget('A moment with '+h.person,53,48,()=>neighborhoodWelcome(h.id),'work');cityTarget('Front door · Willowwood Lane',15,65,neighborhoodLane,'exit');return}neighborhoodHotspotsBefore();if(scene==='home'&&cityInside==='home'){cityTarget('Side door · neighborhood lane',84,65,neighborhoodLane,'path','willowLane')}};
const neighborhoodActionsBefore=cityBuildActions;cityBuildActions=function(){neighborhoodActionsBefore();if(scene!=='home')return;if(!cityInside){for(const b of $('comfortPlaces').querySelectorAll('[data-place]')){if(b.dataset.place!=='home'&&b.dataset.place!=='willowLane')b.closest('.city-action')?.remove()}const lane=$('comfortPlaces').querySelector('[data-place="willowLane"]');if(lane){lane.textContent='Walk down the side lane';lane.closest('.city-action').classList.add('neighborhood-lane-card')}return}if(cityInside==='willowLane'){$('comfortPlaces').replaceChildren();$('comfortPlacesTitle').textContent='The homes along your neighborhood lane';neighborhood.homes.forEach(h=>cityCard(h.name,h.about,'Visit this neighbor’s home',()=>neighborhoodVisit(h.id),'⌂',h.id));cityCard('Back beside your own cottage','The shared lane returns to your front garden.','Return to my cottage entrance',neighborhoodFront,'↶');return}if(neighborhood.home(cityInside)){$('comfortPlaces').replaceChildren();const h=neighborhood.home(cityInside);cityCard(h.name,h.about,'Visit with '+h.person,()=>neighborhoodWelcome(h.id),'♡');cityCard('Step out to the lane','Leave this home through its front door and walk to another neighbor.','Return to Willowwood Lane',neighborhoodLane,'↶');cityCard('Your own cottage','Your belongings and home projects are waiting at your place.','Go to my cottage',()=>{changeScene('home');cityEnter('home')},'⌂');return}if(cityInside==='home'||cityInside==='legacyRoom')cityCard('Your neighborhood is next door','Take the side path beside your cottage to the other homes.','Walk to the neighborhood lane',neighborhoodLane,'⌂')};
const neighborhoodTrailBefore=cityBuildRoomTrail;cityBuildRoomTrail=function(){neighborhoodTrailBefore();if(scene!=='home'||!cityInside)return;const trail=$('cityRoomTrail');trail.replaceChildren();const choices=neighborhoodKinds.includes(cityInside)?[['My cottage','home'],['Neighborhood lane','willowLane'],...neighborhood.homes.map(h=>[h.name,h.id])]:[['My cottage','home'],['My legacy room','legacyRoom'],['Neighborhood lane','willowLane']];for(const [name,kind]of choices){const b=document.createElement('button');b.textContent=name;b.classList.toggle('selected',cityInside===kind);b.dataset.neighborhoodRoute=kind;b.onclick=()=>kind==='willowLane'?neighborhoodLane():cityEnter(kind);trail.append(b)}const exit=document.createElement('button');exit.textContent='↶ My front garden';exit.onclick=neighborhoodFront;trail.append(exit)};
const neighborhoodPeopleBefore=cityBuildPeople;cityBuildPeople=function(){neighborhoodPeopleBefore();if(scene!=='home')return;if(cityInside==='willowLane'||!cityInside){$('cityPeople').replaceChildren();neighborhood.homes.forEach(h=>{const b=document.createElement('button');b.className='city-person';b.textContent=h.person+' · '+h.name;b.onclick=()=>neighborhoodVisit(h.id);$('cityPeople').append(b)})}else if(neighborhood.home(cityInside)){const h=neighborhood.home(cityInside);$('cityPeople').replaceChildren();const b=document.createElement('button');b.className='city-person';b.textContent=h.person+' · '+(neighborhood.present(h.id,atmosphere.conditions(state))?'at home':'a welcome note at the door');b.onclick=()=>neighborhoodWelcome(h.id);$('cityPeople').append(b)}};
const neighborhoodDrawBefore=cityDraw;cityDraw=function(){neighborhoodDrawBefore();if(scene!=='home')return;if(!cityInside){$('subtitle').textContent='Your cottage is here. Follow the lane beside it to the rest of Willowwood’s homes.';$('hint').textContent='Enter your own cottage or take the neighborhood lane on the right.'}if(cityInside==='willowLane'){$('area').textContent='WILLOWWOOD HOMES · OUT ON THE SHARED LANE';$('subtitle').textContent='Four front gardens, four furnished homes, and a path back to your own cottage.';$('cityHere').textContent='Willowwood neighborhood lane';$('cityMap').querySelector('.city-map-center p').textContent='Walking among your neighbors’ homes';$('hint').textContent='Choose a cottage doorway to visit. The path back to your home is behind you.'}if(neighborhood.home(cityInside)){$('area').textContent='WILLOWWOOD HOMES · INSIDE A NEIGHBOR’S COTTAGE';$('subtitle').textContent=neighborhood.home(cityInside).about;$('hint').textContent='You are visiting a neighbor’s furnished home. The front door leads back to Willowwood Lane.'}};comfortDraw=cityDraw;
window.ELDORIA_NEIGHBORHOOD={version:1,openLane:neighborhoodLane,visit:neighborhoodVisit};cityDraw();persist();
